mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RN, INNER_QUERY.* FROM ( SELECT M.MTNG_ID, M.MTNG_NM, M.MTNG_TYPE_CD, M.BEGIN_DT, M.END_DT, M.CRTR_ID, E.EMP_NM AS CRTR_NM, CASE WHEN VC.VCONF_ID IS NULL THEN NULL WHEN M.BEGIN_DT > SYSDATE THEN 'VC001' WHEN M.BEGIN_DT <= SYSDATE AND M.END_DT >= SYSDATE THEN 'VC002' ELSE 'VC003' END AS VCONF_STTUS, VC.VCONF_ID, VC.ROOM_NM, CR.CONF_RM_NM, MOM.MOM_STTUS_CD, ( SELECT COUNT(*) FROM TB_MTNG_PTCPT P WHERE P.MTNG_ID = M.MTNG_ID ) AS PTCPT_CNT, M.DEL_YN FROM TB_MTNG M LEFT JOIN TB_EMPLOYEE E ON E.EMP_ID = M.CRTR_ID LEFT JOIN TB_VIDEO_CONF VC ON VC.MTNG_ID = M.MTNG_ID LEFT JOIN TB_CONF_RM_RSRV RR ON RR.RSRV_ID = M.CONF_RM_RSRV_ID LEFT JOIN TB_CONF_RM CR ON CR.CONF_RM_ID = RR.CONF_RM_ID LEFT JOIN TB_MTNG_MOM MOM ON MOM.MOM_ID = ( SELECT MAX(MOM_ID) FROM TB_MTNG_MOM WHERE MTNG_ID = M.MTNG_ID AND DEL_DT IS NULL ) WHERE 1 = 1
AND M.DEL_YN = 'N'
AND ( M.MTNG_NM LIKE '%' || #{keyword} || '%' OR E.EMP_NM LIKE '%' || #{keyword} || '%' )
AND M.MTNG_TYPE_CD = #{mtngTypeCd}
AND CASE WHEN VC.VCONF_ID IS NULL THEN NULL WHEN M.BEGIN_DT > SYSDATE THEN 'VC001' WHEN M.BEGIN_DT <= SYSDATE AND M.END_DT >= SYSDATE THEN 'VC002' ELSE 'VC003' END = #{vconfSttus}
AND MOM.MOM_STTUS_CD = #{momSttusCd}
AND M.BEGIN_DT >= #{beginDt}
AND M.BEGIN_DT <= #{endDt}
ORDER BY M.BEGIN_DT DESC ) INNER_QUERY WHERE ROWNUM <= #{page} * #{size} ) WHERE RN > (#{page} - 1) * #{size}

SELECT COUNT(*) FROM TB_MTNG M LEFT JOIN TB_EMPLOYEE E ON E.EMP_ID = M.CRTR_ID LEFT JOIN TB_VIDEO_CONF VC ON VC.MTNG_ID = M.MTNG_ID LEFT JOIN TB_MTNG_MOM MOM ON MOM.MOM_ID = ( SELECT MAX(MOM_ID) FROM TB_MTNG_MOM WHERE MTNG_ID = M.MTNG_ID AND DEL_DT IS NULL ) WHERE 1 = 1
AND M.DEL_YN = 'N'
AND ( M.MTNG_NM LIKE '%' || #{keyword} || '%' OR E.EMP_NM LIKE '%' || #{keyword} || '%' )
AND M.MTNG_TYPE_CD = #{mtngTypeCd}
AND MOM.MOM_STTUS_CD = #{momSttusCd}
AND M.BEGIN_DT >= #{beginDt}
AND M.BEGIN_DT <= #{endDt}
